package com.example;

import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.html.UnorderedList;
import com.vaadin.flow.component.orderedlayout.FlexComponent;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.component.dependency.StyleSheet;
import com.vaadin.flow.router.Route;

@Route("")
@StyleSheet("item-tracker.css")
public class ItemsView extends VerticalLayout {

    private final TextField itemField = new TextField("Item");
    private final Button addButton = new Button("Add");
    private final Button clearButton = new Button("Clear");
    private final UnorderedList itemList = new UnorderedList();
    private final Span itemCount = new Span("Items: 0");

    public ItemsView() {
        addClassName("items-view");
        setWidthFull();

        H1 heading = new H1("Items");
        heading.addClassName("items-heading");

        itemField.setWidthFull();
        itemField.setErrorMessage("Enter an item before adding.");

        addButton.setEnabled(true);
        addButton.addThemeVariants(ButtonVariant.PRIMARY);
        addButton.addClickListener(event -> addItem());

        clearButton.setEnabled(true);
        clearButton.addThemeVariants(ButtonVariant.TERTIARY);
        clearButton.addClickListener(event -> clearItems());

        HorizontalLayout controls = new HorizontalLayout(itemField, addButton,
                clearButton);
        controls.addClassName("item-controls");
        controls.setWidthFull();
        controls.setAlignItems(FlexComponent.Alignment.END);

        itemList.addClassName("item-list");
        itemCount.addClassName("item-count");

        add(heading, controls, itemList, itemCount);
    }

    private void addItem() {
        String value = itemField.getValue();
        if (value == null || value.isBlank()) {
            itemField.setInvalid(true);
            return;
        }

        itemField.setInvalid(false);
        itemList.add(new ListItem(value));
        itemField.clear();
        updateCount();
    }

    private void clearItems() {
        itemList.removeAll();
        updateCount();
    }

    private void updateCount() {
        itemCount.setText("Items: " + itemList.getChildren().count());
    }
}
